import pandas as pd


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"]
    cdc_events = inputs["cdc_events"]

    # 1. Distinct by seq (at-least-once delivery -> apply once)
    events = cdc_events.drop_duplicates(subset=["seq"], keep="first").copy()

    # Build initial per-order state from target_state (assumed unique order_id)
    state = {}
    original_state = {}
    for row in target_state.itertuples(index=False):
        rec = {"status": row.status, "amount": row.amount, "last_seq": row.last_seq}
        state[row.order_id] = dict(rec)
        original_state[row.order_id] = dict(rec)

    tombstones = {}

    # Process events grouped per order, in seq order
    for order_id, grp in events.groupby("order_id", sort=False):
        existing = original_state.get(order_id)  # fixed reference for replay guard
        current = state.get(order_id)
        if current is not None:
            current = dict(current)

        ever_had_row = existing is not None
        last_applied_op = None
        last_applied_seq = None

        for ev in grp.sort_values("seq").itertuples(index=False):
            # Replay guard: only applies if order already had a row in target_state
            if existing is not None and ev.seq <= existing["last_seq"]:
                continue

            last_applied_op = ev.op
            last_applied_seq = ev.seq

            if ev.op in ("I", "U"):
                if current is None:
                    current = {
                        "status": ev.status,
                        "amount": ev.amount,
                        "last_seq": ev.seq,
                    }
                else:
                    if ev.op == "U" and pd.isna(ev.amount):
                        new_amount = current["amount"]
                    else:
                        new_amount = ev.amount
                    current = {
                        "status": ev.status,
                        "amount": new_amount,
                        "last_seq": ev.seq,
                    }
                ever_had_row = True
            elif ev.op == "D":
                if current is not None:
                    current = None
                # D on a missing order: no-op, but still "applied"

        if current is not None:
            state[order_id] = current
        else:
            if order_id in state:
                del state[order_id]

        if ever_had_row and last_applied_op == "D":
            tombstones[order_id] = last_applied_seq

    # Build new_state output
    new_state_rows = [
        {
            "order_id": oid,
            "status": v["status"],
            "amount": v["amount"],
            "last_seq": v["last_seq"],
        }
        for oid, v in state.items()
    ]
    new_state = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    if not new_state.empty:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")

    # Build tombstones output
    tomb_rows = [
        {"order_id": oid, "deleted_seq": seq} for oid, seq in tombstones.items()
    ]
    tombstones_df = pd.DataFrame(tomb_rows, columns=["order_id", "deleted_seq"])
    if not tombstones_df.empty:
        tombstones_df["order_id"] = tombstones_df["order_id"].astype("int64")
        tombstones_df["deleted_seq"] = tombstones_df["deleted_seq"].astype("int64")

    return {"new_state": new_state, "tombstones": tombstones_df}
